    state.activeDmMemberId = memberId
    state.activeChannelId = null
  },
  setChannelMessages(state, { teamId, channelId, messages }) {
    const key = `${teamId}/${channelId}`
    state.channelMessages[key] = messages
  },
  addChannelMessage(state, { teamId, channelId, message }) {
    const key = `${teamId}/${channelId}`
    if (!state.channelMessages[key]) state.channelMessages[key] = []
    state.channelMessages[key].push(message)
  },
  updateChannelMessage(state, { teamId, channelId, messageId, content }) {
    const key = `${teamId}/${channelId}`
    const messages = state.channelMessages[key] || []
    const msg = messages.find(m => m.id === messageId)
    if (msg) msg.content = content
  },
  removeChannelMessage(state, { teamId, channelId, messageId }) {
    const key = `${teamId}/${channelId}`
    const messages = state.channelMessages[key] || []
    const idx = messages.findIndex(m => m.id === messageId)
    if (idx >= 0) messages.splice(idx, 1)
  },
  setDMMessages(state, { teamId, memberId, messages }) {
    const key = `${teamId}/${memberId}`
    state.dmMessages[key] = messages
  },
  addDMMessage(state, { teamId, memberId, message }) {
    const key = `${teamId}/${memberId}`
    if (!state.dmMessages[key]) state.dmMessages[key] = []
    state.dmMessages[key].push(message)
  },
  updateDMMessage(state, { teamId, memberId, messageId, content }) {
    const key = `${teamId}/${memberId}`
    const messages = state.dmMessages[key] || []
    const msg = messages.find(m => m.id === messageId)
    if (msg) msg.content = content
  },
  removeDMMessage(state, { teamId, memberId, messageId }) {
    const key = `${teamId}/${memberId}`
    const messages = state.dmMessages[key] || []
    const idx = messages.findIndex(m => m.id === messageId)
    if (idx >= 0) messages.splice(idx, 1)
  },
  setTypingUsers(state, { teamId, channelId, users }) {
    const key = `${teamId}/${channelId}`
    state.typingUsers[key] = users
  },
  setOnlineMembers(state, { teamId, members }) {
    state.onlineMembers[teamId] = members
  },
  setMessageLoading(state, loading) {
    state.messageLoading = loading
  }
})

export const getters = getterTree(state, {
  activeTeam: state => state.teams.find(t => t.id === state.activeTeamId),
  activeChannelInfo: state => {
    const team = state.teams.find(t => t.id === state.activeTeamId)
    if (!team) return null
    return team.categories
      ?.flatMap(c => c.channels)
      ?.find(ch => ch.id === state.activeChannelId)
  },
  activeDmMemberInfo: state => {
    const team = state.teams.find(t => t.id === state.activeTeamId)
    if (!team || !state.activeDmMemberId) return null
    return team.members?.find(m => m.id === state.activeDmMemberId)
  },
  currentMessages: state => {
    if (state.activeChannelId) {
      const key = `${state.activeTeamId}/${state.activeChannelId}`
      return state.channelMessages[key] || []
    }
    if (state.activeDmMemberId) {
      const key = `${state.activeTeamId}/${state.activeDmMemberId}`
      return state.dmMessages[key] || []
    }
    return []
  },
  currentTypingUsers: state => {
    if (!state.activeChannelId) return []
    const key = `${state.activeTeamId}/${state.activeChannelId}`
    return state.typingUsers[key] || []
  },
  teamOnlineMembers: state => {
    return state.onlineMembers[state.activeTeamId] || {}
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async loadChannelMessages({ state, commit }, { teamId, channelId }) {
      commit('setMessageLoading', true)
      try {
        const messages = await API.teams.getMessages(teamId, channelId)
        commit('setChannelMessages', { teamId, channelId, messages })
      } catch (error) {
        console.error('[teams] loadChannelMessages error:', error)
      } finally {
        commit('setMessageLoading', false)
      }
    },

    async loadDMMessages({ state, commit }, { teamId, memberId }) {
      commit('setMessageLoading', true)
      try {
        const messages = await API.teams.getDMMessages(teamId, memberId)
        commit('setDMMessages', { teamId, memberId, messages })
      } catch (error) {
        console.error('[teams] loadDMMessages error:', error)
      } finally {
        commit('setMessageLoading', false)
      }
    },

    async sendMessage({ state, commit }, { teamId, channelId, content, attachments = [] }) {
      try {
        const message = await API.teams.sendMessage(teamId, channelId, {
          content,
          attachments
        })
        commit('addChannelMessage', { teamId, channelId, message })
        return message
      } catch (error) {
        console.error('[teams] sendMessage error:', error)
        throw error
      }
    },

    async sendDMMessage({ state, commit }, { teamId, memberId, content, attachments = [] }) {
      try {
        const message = await API.teams.sendDMMessage(teamId, memberId, {
          content,
          attachments
        })
        commit('addDMMessage', { teamId, memberId, message })
        return message
      } catch (error) {
        console.error('[teams] sendDMMessage error:', error)
        throw error
      }
    },

    async editMessage({ state, commit }, { teamId, channelId, messageId, content }) {
      try {
        await API.teams.editMessage(teamId, channelId, messageId, { content })
        commit('updateChannelMessage', { teamId, channelId, messageId, content })
      } catch (error) {
        console.error('[teams] editMessage error:', error)
        throw error
      }
    },

    async editDMMessage({ state, commit }, { teamId, memberId, messageId, content }) {
      try {
        await API.teams.editDMMessage(teamId, memberId, messageId, { content })
        commit('updateDMMessage', { teamId, memberId, messageId, content })
      } catch (error) {
        console.error('[teams] editDMMessage error:', error)
        throw error
      }
    },

    async deleteMessage({ state, commit }, { teamId, channelId, messageId }) {
      try {
        await API.teams.deleteMessage(teamId, channelId, messageId)
        commit('removeChannelMessage', { teamId, channelId, messageId })
      } catch (error) {
        console.error('[teams] deleteMessage error:', error)
        throw error
      }
    },

    async deleteDMMessage({ state, commit }, { teamId, memberId, messageId }) {
      try {
        await API.teams.deleteDMMessage(teamId, memberId, messageId)
        commit('removeDMMessage', { teamId, memberId, messageId })
      } catch (error) {
        console.error('[teams] deleteDMMessage error:', error)
        throw error
      }
    },

    setTypingUser({ state, commit }, { teamId, channelId, userId, username }) {
      const key = `${teamId}/${channelId}`
      const users = state.typingUsers[key] || []
      if (!users.find(u => u.userId === userId)) {
        commit('setTypingUsers', { teamId, channelId, users: [...users, { userId, username }] })
        setTimeout(() => {
          const updated = (state.typingUsers[key] || []).filter(u => u.userId !== userId)
          commit('setTypingUsers', { teamId, channelId, users: updated })
        }, 3000)
      }
    },

    selectChannel({ commit }, { teamId, channelId }) {
      commit('setActiveChannel', { teamId, channelId })
    },

    selectDmMember({ commit }, { teamId, memberId }) {
      commit('setActiveDmMember', { teamId, memberId })
    }
  }
)

